    std::optional<double> degrees;
    /// How the orbit composes with the selected timesteps.
    std::optional<para_view_turntable_time_mode> time_mode;
    /// The orbit axis through the focal point.
    std::optional<para_view_turntable_axis> axis;
    /// Total rise of the camera in degrees about its own right axis through the focal point (positive = the camera climbs toward the view-up, toward a top-down view; negative = it dives). 0 keeps the captured height; at most ±170 so the move never crosses the pole. Appended in Model 0.4.0.
